import glob, yaml, os

TODAY="2026-06-11"; WARN="2026-06-30"; GEN_DATE="2026-06-11"
IND_FILES=[("製造業","manufacturing.md"),("科技業","technology.md"),("服務業","services.md"),
    ("零售業","retail.md"),("農業","agriculture.md"),("醫療業","healthcare.md"),
    ("設計業","design.md"),("全產業","all-industries.md")]

def extract_fm(txt):
    lines=txt.splitlines()
    if not lines or lines[0].strip()!="---": return None
    for i in range(1,len(lines)):
        if lines[i].strip()=="---":
            return "\n".join(lines[1:i])
    return None

progs=[]; errors=[]
for path in sorted(glob.glob("programs/*.md")):
    txt=open(path,encoding="utf-8").read()
    fm=extract_fm(txt)
    if fm is None:
        errors.append((os.path.basename(path),"no frontmatter")); continue
    try:
        data=yaml.safe_load(fm)
    except Exception as e:
        errors.append((os.path.basename(path),str(e).splitlines()[0])); continue
    if not data or data.get("status")!="active": continue
    data["_file"]=os.path.basename(path); progs.append(data)

print("PARSE ERRORS:", len(errors))
for f,e in errors: print("  ",f,"=>",e)
print("Parsed active:", len(progs))
PYEOF
